begin;
alter table public.movies drop constraint "movies_posterUrl_check";
alter table public.movies add constraint "movies_posterUrl_check" check("posterUrl"='' or "posterUrl" ~ '^https://' or "posterUrl" ~ '^/assets/posters/[a-z0-9-]+\.(svg|jpg)$');
select 'Иван Васильевич меняет профессию','Машина времени соединяет московскую квартиру с палатами Ивана Грозного. Управдом и царь невольно меняются местами.',1973,88,(select "directorID" from public.directors where "fullName"='Леонид Гайдай' order by "directorID" limit 1),(select "genreID" from public.genres where "genreName"='Comedy' order by "genreID" limit 1),(select "actorID" from public.actors where "fullName"='Леонид Куравлев' order by "actorID" limit 1),0,'/assets/posters/ivan-vasilevich-menyaet-professiyu.jpg','https://www.mosfilm.ru/cinema/films/ivan-vasilevich-menyaet-professiyu/','https://rutube.ru/play/embed/de108b940b59e5e9d361077328ca9201/','https://www.mosfilm.ru/cinema/films/ivan-vasilevich-menyaet-professiyu/','© Киноконцерн «Мосфильм». Официальный плеер правообладателя. Все права защищены.',true,array['happy','cozy'],array['Полный фильм','Мосфильм','На русском'],1,true,'Русский'
where not exists(select 1 from public.movies where title='Иван Васильевич меняет профессию' and "releaseYear"=1973);
select 'Операция "Ы" и другие приключения Шурика','Три комедийные истории о студенте Шурике: работа на стройке, подготовка к экзамену и ночное дежурство на складе.',1965,96,(select "directorID" from public.directors where "fullName"='Леонид Гайдай' order by "directorID" limit 1),(select "genreID" from public.genres where "genreName"='Comedy' order by "genreID" limit 1),(select "actorID" from public.actors where "fullName"='Александр Демьяненко' order by "actorID" limit 1),0,'/assets/posters/operatsiya-y-i-drugie-priklyucheniya-shurika.jpg','https://www.mosfilm.ru/cinema/films/operatsiya-y-i-drugie-priklyucheniya-shurika/','https://rutube.ru/play/embed/fcb693c38528938caa3b70101b7c58bf/','https://www.mosfilm.ru/cinema/films/operatsiya-y-i-drugie-priklyucheniya-shurika/','© Киноконцерн «Мосфильм». Официальный плеер правообладателя. Все права защищены.',true,array['happy','cozy'],array['Полный фильм','Мосфильм','На русском'],1,true,'Русский'
where not exists(select 1 from public.movies where title='Операция "Ы" и другие приключения Шурика' and "releaseYear"=1965);
select 'Бриллиантовая рука','Скромный турист случайно оказывается участником операции контрабандистов и помогает разоблачить преступников.',1968,100,(select "directorID" from public.directors where "fullName"='Леонид Гайдай' order by "directorID" limit 1),(select "genreID" from public.genres where "genreName"='Comedy' order by "genreID" limit 1),(select "actorID" from public.actors where "fullName"='Андрей Миронов' order by "actorID" limit 1),0,'/assets/posters/brilliantovaya-ruka.jpg','https://www.mosfilm.ru/cinema/films/brilliantovaya-ruka/','https://rutube.ru/play/embed/1a7baf7b3eb80925774b0174b1e2c0f9/','https://www.mosfilm.ru/cinema/films/brilliantovaya-ruka/','© Киноконцерн «Мосфильм». Официальный плеер правообладателя. Все права защищены.',true,array['happy','cozy'],array['Полный фильм','Мосфильм','На русском'],1,true,'Русский'
where not exists(select 1 from public.movies where title='Бриллиантовая рука' and "releaseYear"=1968);
select 'Кавказская пленница, или Новые приключения Шурика','Шурик приезжает на Кавказ собирать фольклор и оказывается втянут в похищение студентки Нины.',1966,82,(select "directorID" from public.directors where "fullName"='Леонид Гайдай' order by "directorID" limit 1),(select "genreID" from public.genres where "genreName"='Comedy' order by "genreID" limit 1),(select "actorID" from public.actors where "fullName"='Александр Демьяненко' order by "actorID" limit 1),0,'/assets/posters/kavkazskaya-plennitsa-ili-novye-priklyucheniya-shurika.jpg','https://www.mosfilm.ru/cinema/films/kavkazskaya-plennitsa-ili-novye-priklyucheniya-shurika/','https://rutube.ru/play/embed/2959f7a99504290930cc68951bd2f5ce/','https://www.mosfilm.ru/cinema/films/kavkazskaya-plennitsa-ili-novye-priklyucheniya-shurika/','© Киноконцерн «Мосфильм». Официальный плеер правообладателя. Все права защищены.',true,array['happy','cozy'],array['Полный фильм','Мосфильм','На русском'],1,true,'Русский'
where not exists(select 1 from public.movies where title='Кавказская пленница, или Новые приключения Шурика' and "releaseYear"=1966);
select 'Любовь и голуби','После поездки на курорт Василий пытается разобраться в своих чувствах и вернуть доверие семьи.',1984,105,(select "directorID" from public.directors where "fullName"='Владимир Меньшов' order by "directorID" limit 1),(select "genreID" from public.genres where "genreName"='Comedy' order by "genreID" limit 1),(select "actorID" from public.actors where "fullName"='Александр Михайлов' order by "actorID" limit 1),0,'/assets/posters/lyubov-i-golubi.jpg','https://www.mosfilm.ru/cinema/films/lyubov-i-golubi/','https://rutube.ru/play/embed/68781d890618ea50933ec020fd5060bf/','https://www.mosfilm.ru/cinema/films/lyubov-i-golubi/','© Киноконцерн «Мосфильм». Официальный плеер правообладателя. Все права защищены.',true,array['happy','cozy'],array['Полный фильм','Мосфильм','На русском'],2,true,'Русский'
where not exists(select 1 from public.movies where title='Любовь и голуби' and "releaseYear"=1984);
